// Shippo requests always go through the private Site's test-token-only backend.
let quote=null,rateId=null;
function errorRate(message){$('rateError').textContent=message;$('rateError').classList.remove('hidden')}
function clearRates(){quote=null;rateId=null;$('rates').classList.add('hidden');$('testLabel').classList.add('hidden');$('rateError').classList.add('hidden');$('rateChoices').replaceChildren()}
function addr(prefix){const v=x=>$(prefix+x).value.trim();return {name:v('Name'),street1:v('Street'),city:v('City'),state:v('State').toUpperCase(),zip:v('Zip'),country:'US',...(v('Phone')?{phone:v('Phone')}:{})}}
function completeAddress(a){return a.name&&a.street1&&a.city&&a.state&&a.zip}
async function shippoRequest(path,body){const r=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify(body)}),d=await r.json().catch(()=>({error:'Unreadable response'}));if(!r.ok)throw Error(d.error||'Shippo test request failed');return d}
async function shippoStatus(){try{const r=await fetch('/api/shippo/status',{credentials:'same-origin'}),d=await r.json();$('shippoStatus').textContent=d.configured?'TEST token connected':'Test token needed';$('shippoStatus').className='pill '+(d.configured?'':'warn');$('getRates').disabled=!d.configured}catch{$('shippoStatus').textContent='Integration unavailable';$('getRates').disabled=true}}
function syncRecipient(){if(!current())return;$('toName').value=$('recipient').value;$('toPhone').value=$('phone').value;clearRates()}
new MutationObserver(syncRecipient).observe($('title'),{childList:true,subtree:true,characterData:true});
$('resetRates').onclick=clearRates;
$('getRates').onclick=async()=>{clearRates();save();const g=current();if(!g)return errorRate('Select a customer first');const s=state(g);if(!s.verified)return errorRate('Verify review and physical packing before quoting');const from=addr('from'),to=addr('to');if(!completeAddress(from)||!completeAddress(to))return errorRate('Complete sender and recipient address fields');const parcel={length:Number(s.length),width:Number(s.width),height:Number(s.height),weight:Number(s.weight),distance_unit:'in',mass_unit:'kg'};if([parcel.length,parcel.width,parcel.height,parcel.weight].some(x=>!Number.isFinite(x)||x<=0))return errorRate('Enter positive weight and dimensions');$('getRates').disabled=true;$('getRates').textContent='Quoting…';try{const d=await shippoRequest('/api/shippo/rates',{from,to,parcel});quote={customer:g.key,shipment:d.shipment_id};const rates=(d.rates||[]).filter(x=>['USPS','UPS'].includes(x.provider)).sort((a,b)=>Number(a.amount)-Number(b.amount));$('rates').classList.remove('hidden');$('rateChoices').innerHTML=rates.length?rates.map((x,i)=>'<div class="flag"><label><input type="radio" name="testRate" value="'+esc(x.id)+'" '+(i===0?'checked':'')+'>'+esc(x.provider)+' · '+esc(x.service)+' · '+esc(x.amount)+' '+esc(x.currency)+'</label></div>').join(''):'<div class="note">No USPS/UPS test rates returned. Review carrier configuration and addresses.</div>';rateId=rates[0]?.id||null;$('rateChoices').querySelectorAll('[name="testRate"]').forEach(el=>el.onchange=()=>rateId=el.value)}catch(e){errorRate(e.message)}finally{$('getRates').textContent='Get test rates';$('getRates').disabled=false}};
$('createTestLabel').onclick=async()=>{const g=current();if(!g||!quote||quote.customer!==g.key)return errorRate('Request rates for the current customer');if(!rateId)return errorRate('Choose a test rate');$('createTestLabel').disabled=true;try{const d=await shippoRequest('/api/shippo/test-label',{rate_id:rateId});if(!d.was_test)throw Error('No test confirmation received');$('testLabel').replaceChildren();const head=document.createElement('b');head.textContent='TEST LABEL · '+d.status;$('testLabel').append(head);const p=document.createElement('p');p.textContent='Test tracking: '+(d.tracking_number||'Unavailable');$('testLabel').append(p);if(d.label_url){const link=document.createElement('a');link.href=d.label_url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Open TEST label PDF';$('testLabel').append(link)}$('testLabel').classList.remove('hidden')}catch(e){errorRate(e.message)}finally{$('createTestLabel').disabled=false}};
shippoStatus();
